const header=document.querySelector('header');
const menu=document.querySelector('.menu-toggle');
menu.addEventListener('click',()=>{const open=header.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');menu.textContent=open?'×':'☰'});
const details=document.querySelector('.product-menu');
document.addEventListener('click',e=>{if(!details.contains(e.target))details.open=false});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){details.open=false;header.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰'}});
const lightbox=document.querySelector('.lightbox');
document.querySelectorAll('.content-page a[href]').forEach(a=>{if(/\.(jpg|jpeg|png|webp)(\?.*)?$/i.test(a.href)&&a.querySelector('img'))a.addEventListener('click',e=>{e.preventDefault();lightbox.querySelector('img').src=a.href;lightbox.showModal()})});
lightbox.querySelector('button').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});
const ps=document.querySelector('#product-search');
if(ps){const products=[...document.querySelectorAll('.directory-product')];const filter=()=>{const q=ps.value.trim().toLowerCase();let count=0;products.forEach(p=>{p.hidden=!p.dataset.title.includes(q);if(!p.hidden)count++});document.querySelector('#product-count').textContent=count?`${count} product${count===1?'':'s'}`:'No products found. Try another search.'};ps.addEventListener('input',filter);filter()}
const ds=document.querySelector('#dealer-search');
const clean=v=>{const el=document.createElement('span');el.innerHTML=v||'';return el.textContent};
if(ds){fetch('/dealers.json').then(r=>{if(!r.ok)throw Error('Directory unavailable');return r.json()}).then(dealers=>{const results=document.querySelector('#dealer-results');const filter=()=>{const q=ds.value.toLowerCase().replace(/\s/g,'');const matches=dealers.filter(d=>[d.store,d.city,d.state,d.zip,d.address].join(' ').toLowerCase().replace(/\s/g,'').includes(q));results.replaceChildren();document.querySelector('#dealer-count').textContent=matches.length?`${matches.length} dealers found`:'No matching dealers. Try a city or province, or call 1-800-665-1027 for assistance.';matches.forEach(d=>{const card=document.createElement('article');card.className='dealer-card';const location=document.createElement('div');location.className='dealer-location';location.textContent=`${d.city}, ${d.state}`;const title=document.createElement('h2');title.textContent=clean(d.store);const address=document.createElement('p');address.textContent=[d.address,d.address2,d.city,d.state,d.zip].filter(Boolean).map(clean).join(', ');card.append(location,title,address);const addLink=(url,label)=>{const a=document.createElement('a');a.href=url;a.textContent=label;card.append(a)};if(d.phone)addLink('tel:'+d.phone.replace(/[^+\d]/g,''),d.phone);if(d.email)addLink('mailto:'+d.email,d.email);if(d.url&&/^https?:/.test(d.url))addLink(d.url,'Visit dealer website ↗');addLink('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent([clean(d.store),d.address,d.city,d.state].join(' ')),'Get directions ↗');results.append(card)})};ds.addEventListener('input',filter);filter()}).catch(()=>{document.querySelector('#dealer-count').textContent='Please call 1-800-665-1027 for help finding your nearest dealer.'})}
